// msdfgen-config.h

// Define the library version (optional, but good practice)
#define MSDFGEN_VERSION 10000

// Define this if you need support for C++ shapes, usually recommended
#define MSDFGEN_USE_CPP_SHAPES 1

// Define this if you are using C++ streams, also good to have
#define MSDFGEN_USE_CPP_STREAMS 1

// If you want to use advanced features like SSE or AVX, you would define
// them here based on platform, but for a simple fix, these are sufficient.
// #define MSDFGEN_USE_SSE
// #define MSDFGEN_USE_AVX